from pathlib import Path
import json
O=Path(__file__).resolve().parents[1]; B={b['id']:b for b in json.loads((O/'_source/blocks.json').read_text())};P=[]
def add(i,new,reason,old=None,cat='表达与论证'):
 k=f'B{i:04d}';old=B[k]['text'] if old is None else old
 assert old in B[k]['text'],(k,old)
 P.append(dict(block_id=k,old_text=old,new_text=new,reason=reason,category=cat))
add(6,'端到端论辩挖掘需要同时定位组件、判别论辩角色并抽取有向关系。组件与关系之间的依赖，使训练文本的局部改写可能破坏原有监督，也使预测组件的修改可能导致关系端点失效。本文在多候选重排序与有界修正的基础上，研究训练与推理两个阶段的依赖维护。','明确局部改写和预测修正分别作用于训练与推理，减少代词跳转。')
add(7,'训练阶段通过关系影响域识别内部、跨边界及NONE因素，利用无损标注输运和逐因素掩码建立可靠对应。原文保留完整图生成监督，增强视图仅对可靠组件与关系提供辅助监督和分布对齐约束。推理阶段将组件变化及全部受影响关系纳入依赖闭合事务，在冻结的完整对象评分下，结合分项效用门和编辑预算决定是否接受修改，并支持局部与全局两种求解路径。CDCP的多源关系始终按完整超边计数。','拆开过长方法句，统一阶段、增强视图和效用门术语。')
add(8,'在AAEC和CDCP官方测试划分及自由预测数量协议下，Qwen3.5-9B完整配置的严格关系F1分别为71.63和50.77，相对同骨干ICIC/MCR-BR基线提高5.94和8.98个百分点。固定I0时，训练增量分别为2.56和3.30个百分点；固定T1时，追加修正增量分别为3.38和5.68个百分点。在14项主要比较的Holm校正后，两种语料的追加推理增量及CDCP训练增量达到统计显著性，AAEC训练增量未达到统计显著性。Qwen3.5-4B和Qwen2.5-7B-Instruct的补充实验支持共享增强条件下的方法迁移。弱评分回退与失败案例进一步表明，固定效用的提高并不保证每个样本的抽取质量改善。','依据作者确认采用实验表述，显著性明确对应比较族；摘要结尾说明研究边界而非列材料。')
add(11,'End-to-end argument mining requires the joint identification of text spans, argumentative roles, and directed relations. Dependencies between components and relations create challenges at two stages: local paraphrasing can invalidate training labels, and component edits can invalidate relation endpoints during prediction repair. Building on multi-candidate reranking and bounded repair, this thesis studies dependency maintenance during training and inference.','英文摘要与中文问题陈述对齐。')
add(12,'During training, relation influence domains identify internal, cross-boundary, and NONE factors. Lossless annotation transport and factor-level masks establish reliable correspondences for auxiliary supervision and paired distribution alignment, while original documents retain full-graph generation targets. During inference, dependency-closed transactions jointly reconsider component changes and all affected relations. Frozen full-object scores, separate utility gates, and edit budgets determine whether to accept a transaction. Local and global optimization use the same object identities and structural constraints. Multi-source relations in CDCP are evaluated as complete native hyperedges.','统一英文术语，避免误称局部累计预算与全局净预算完全相同。')
add(13,'On the official AAEC and CDCP test splits under free-cardinality evaluation, the complete Qwen3.5-9B configuration achieves strict relation F1 scores of 71.63 and 50.77, exceeding the same-backbone ICIC/MCR-BR baseline by 5.94 and 8.98 percentage points. With I0 fixed, the training gains are 2.56 and 3.30 points; with T1 fixed, the additional repair gains are 3.38 and 5.68 points. After Holm correction across fourteen primary comparisons, both additional inference gains and the CDCP training gain are statistically significant, whereas the AAEC training gain is not. Supplementary experiments with Qwen3.5-4B and Qwen2.5-7B-Instruct support transfer under shared augmentation. Weak-score abstention and failure cases show that improved fixed utility does not guarantee better extraction for every instance.','消除scenario records遗留表达，与中文摘要的数值、显著性和边界逐项一致。')
add(782,'第三章研究训练文本改写后的监督保持，第四章研究预测组件修改后的关系依赖。本章在相同骨干、自由预测数量和原生完整对象评价条件下，通过四种训练与推理组合、完整关系对象对齐及漏检环节分析，考察两阶段的组合效果。','纠正训练前后对应的含糊时间关系，展开压缩术语。')
add(784,'本章沿用第二章的官方测试划分、原生对象身份和严格评价规则，以包含BR-O的T0I0作为完整基线，在相同测试文档和三个种子上比较四种组合。T1I0采用第三章的训练配置并保留继承推理流程；T0I1保留基线训练配置，在对应I0终态上追加第四章的依赖闭合修正R_DC；T1I1同时采用新增训练配置与追加修正。四种组合为区分训练增量、追加推理增量及二者的交互提供共同参照。','统一配置命名，准确保留I0完整链及追加修正身份。')
add(785,'各层次比较的解释范围见表5-1。固定I0的比较考察整套训练配置；固定T1的比较从相同I0终态出发，考察追加依赖闭合修正R_DC的条件增量；四种组合的比较进一步分析增益重叠与交互。成对目标、共同接受和集合动作等具体机制的贡献，仍由相应受控比较判断。','压缩与前段重复的设置叙述，保留机制归因边界。')
add(787,'两阶段组合','以规范术语替代四格。',old='两阶段四格',cat='术语统一')
add(787,'外部系统','删除含糊的具名标签。',old='具名外部',cat='术语统一')
add(787,'CPU诊断案例','区分诊断案例与主模型实验。',old='真实CPU案例',cat='术语统一')
add(788,'继承协议核查与外部系统比较分别解释。补充表S2-1核查原MCR-BR协议下的继承配置，附录E转录其已公开结果，二者均不与本章严格评价数值混合汇总。附录G的UniASA及Kawarada等的TextToText适配到相同骨干并采用共同评价器，同时保留各自任务建模方式与公开接口，因此用于系统层面的比较。CPU诊断案例来自CPU-BIO-SGD在训练侧拟合后的测试预测及固定规则处理，用于说明可复核的错误变化。','与附录G统一外部系统均适配9B的条件，避免误认为骨干不同。')
add(794,'在Qwen3.5-9B上，T1I1的组件F1和严格关系F1均值在两种语料中均高于其余三种配置。关系F1分别为71.63和50.77，对应T0I0基线为65.69和41.79。由于比较使用相同骨干，这一差异反映固定骨干条件下完整方法配置的效果。','明确比较对象为T0I0，区分均值排序和统计显著性。')
add(796,'表5-3区分主要比较与探索性比较，并列出平均配对差值、其95%置信区间及三个种子的配对差值。表5-2的均值与表5-3的差值分别由未舍入的逐种子结果计算，再保留两位小数，因此展示均值相减可能与配对差值相差0.01个百分点。下文采用表5-3的配对差值。','消除“逐种子差值及其区间”可能被理解为每个种子独立区间的歧义，规范单位。')
add(797,'表5-3 四种配置的关系F1差值与交互','规范表题。')
add(799,'固定I0时，AAEC和CDCP的训练增量分别为2.56和3.30个百分点；固定T1时，追加修正增量分别为3.38和5.68个百分点。14项主要比较经Holm校正后，CDCP训练增量及两种语料的追加推理增量达到统计显著性，AAEC训练增量未达到统计显著性。完整配置相对基线的总增量为5.94和8.98个百分点，该比较保持探索性分析身份。','删去与上一小节重复的主结果，保留条件增量及总增量的探索性身份。')
add(800,'交互项定义为(T1I1−T1I0)−(T0I1−T0I0)。AAEC的估计值为-0.35个百分点，95%置信区间为[-0.85, 0.03]；CDCP为-0.22个百分点，区间为[-0.95, 0.35]。两个区间均包含零，因此现有证据不足以确认正向协同或负向交互，也不能据此认定两阶段完全独立。图5-1展示四种配置的总体表现，5.3节进一步分析其恢复对象的重叠。','区间包含零不等于无交互；明确图与后续对象分析的关系。')
add(802,'图5-1 两种语料上四种配置的关系F1','规范图题。')
add(806,'表5-4以T0I0正确识别的关系为基准，按完整关系的规范键对齐两条单独路径与完整配置新增的TP。仅当文档、完整源集合、目标和关系标签一致时，才将其视为同一对象。由此区分两阶段共同恢复、各自独有及仅在组合后恢复的关系。表中计数为三个种子合计，用于对象分解，与逐种子F1均值采用不同的汇总方式。','解释同一对象的判据，规范源语义键表达。')
add(810,'训练与追加修正恢复了部分不同的完整关系：AAEC分别独有82条和31条，共同恢复6条，组合独有1条；CDCP分别独有28条和20条，共同恢复2条，组合独有0条。这说明两条路径的恢复对象并不完全重合，但不能据此推断F1存在正向交互。','保留全部计数，连接对象差异与统计交互边界。')
add(814,'表5-5a 四种配置的金标关系端点与选择分解','替换四格及不必要的复合标题。')
add(816,'与T0I0相比，T1I1在AAEC上将端点缺失关系由637条减少至517条，但端点齐全而未选中的关系由132条增加至174条；CDCP的端点缺失关系由294条减少至251条，端点齐全而未选中的关系仍为119条。因此，端点恢复的改善并不意味着关系选择环节同步改善。','将重复数字描述改为由表格直接支持的分析结论。')
add(818,'表5-5b T1I1未命中关系的首个阻断环节','统一配置和诊断名词。')
add(820,'在既定归类顺序下，两种语料的未命中关系主要分布在终态端点缺失和评分未过门两个环节。AAEC分别为517条和167条，CDCP分别为251条和114条；完整槽位未入池分别为6条和5条。AAEC另有1条归于联合约束或接受门，CDCP该项为0条；两种语料的未评分和超时项均为0。','保留诊断数值，突出主要分布，避免再次重复归类原则。')
add(827,'CDCP单源组中，T0I0至T1I1的TP由309增加至349，FP由494减少至342。多源关系按完整源集合匹配，组内F1的提高也可能来自误报减少，因此不能将F1增量直接解释为新增完整关系的数量。','用误报替换误边，避免完整超边与二元边混用。')
add(828,'四源及以上关系在T1I1中为TP=4、FP=11、FN=20。该组测试集仅含8条独立关系，三个种子的重复评价不增加独立对象数量。因此，这些结果用于描述长源集合的恢复困难，不作额外的显著性推断。','规范金标供给及显著性主张措辞。')
add(831,'Qwen3.5-9B用于主实验、完整消融与错误分析；Qwen3.5-4B用于考察同系列较小骨干，Qwen2.5-7B-Instruct用于衔接已有生成式基线。三者使用相同原生划分、种子、自由预测数量协议，以及由9B生成并审核的增强视图，同时分别配置抽取生成器G、对象评分器S、源组提案器P、OOF校准和开发策略。因此，该实验考察共享增强条件下的方法迁移，4B仍使用较强模型提供的增强数据，跨版本差异也不能解释为纯参数规模效应。','展开模块名称，统一骨干全称与跨骨干结论范围。')
add(832,'表5-7 三种骨干的四种配置结果（均值 ± SD）','规范表题。')
add(834,'表5-7分别列出各骨干的基线与完整配置。Qwen3.5-9B在两种语料上均具有较高的基线和最终均值，其完整配置相对同骨干基线的关系F1增量为5.94和8.98个百分点；4B为6.64和10.61个百分点，Qwen2.5-7B-Instruct为6.88和11.56个百分点。在本实验中，较高基线对应较小的追加改善空间，但这些比较尚不能确定参数规模与增益之间的因果关系。','保留增量数值；把描述性排序与参数规模效应区分开。')
add(837,'补充比较族包含2种骨干、2种语料和3项比较，共12项，使用与主实验相同的2000次文档与种子重采样索引，并单独进行Holm校正。表5-8所列增量均为正，且校正后达到统计显著性；这些检验不改变9B主实验14项比较的校正结果。结论仍限于两个语料和三个种子的共享增强设置，不能据此推断所有模型或领域均具有相同增益。','明确独立多重比较族与有限推广范围。')
add(839,'本章结合总体指标、完整关系对象和漏检分布分析了两阶段的组合效果。四种配置均显示正向的阶段条件增量，其中AAEC训练增量未通过主要比较族的Holm校正。两条单独路径恢复的关系部分不同，但完整配置仍会丢失部分原有正确关系，交互区间也不足以确认稳定协同。终态端点缺失与评分未过门是当前漏检诊断中的主要环节，CDCP长源集合的恢复仍然困难。共享增强条件下的跨骨干结果补充了方法的适用性证据；具体机制的贡献仍需结合各自受控比较判断。','小结保留不显著例外、正确关系损失和跨骨干新增结果，避免少量等无依据修饰。')
add(844,'在AAEC和CDCP上，Qwen3.5-9B完整配置的严格关系F1分别为71.63和50.77，相对同骨干ICIC/MCR-BR基线提高5.94和8.98个百分点。固定I0的训练增量分别为2.56和3.30个百分点，固定T1的追加修正增量分别为3.38和5.68个百分点。经14项主要比较的Holm校正，CDCP训练增量及两种语料的追加推理增量达到统计显著性，AAEC训练增量未达到统计显著性。共享增强条件下的跨骨干实验进一步支持了方法在所测试模型间的迁移，具体配置见附录K。','在总结中明确语料顺序，删去交付过程说明，统一检验措辞。')
add(845,'机制贡献由对应受控比较判断。成对项在CDCP上的增量通过主要比较族的Holm校正，在AAEC上未通过；共同接受、集合动作及等预算重生成比较仍不足以支持跨语料的稳定优势。因此，系统总体增益不能全部归于单个损失项或动作。CPU参考事务与独立规则案例用于补充过程分析，并保留失败情形。','去除“刚通过”口语，不用总体增益替代单机制证据。')
add(847,'固定效用上升不保证严格F1上升。主配置中，AAEC有14/240条、CDCP有3/450条文档与种子组合记录的指标下降；额外评分和搜索也增加了计算成本。弱评分版本v0未满足开发集原TP保留要求，因而触发回退。这表明，扩大动作空间之前需要检验决策区域的评分质量及其对原有正确关系的影响。','明确分母单位和回退原因，保留数值。')
add(848,'本实验仅使用三个种子，且CDCP长源关系样本较少，细粒度比较的估计精度因而受限。增强池中各审核层的不安全率及区间存在差异，整体较低的漂移率不能保证每一层均满足同等可靠性要求。CasiMedicos转换文件有69条缺少正文，ArgUNSC没有独立官方测试划分；本文仅用二者核对文本与原生标注结构，不据此推断跨语言、医学判断或跨域泛化效果。','明确局限影响的推断对象，避免将区间本身写成高于另一种统计量。')
add(850,'后续研究可优先围绕三个限制展开：针对长源集合漏检，改进完整源组提案并增加相应独立测试样本；针对效用与严格F1不一致，考察决策区域的代价敏感校准；针对额外推理开销，比较低成本对象评分与集合动作在质量和资源消耗上的收益。同时，应在新增领域语料上检验共享增强设置下的效果能否保持。是否扩大集合动作范围，应由独立的质量与成本比较决定。','使展望逐项回应已观察限制，不新增已完成实验。')
